    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.xls'):
            # simple read to see structure
            df = pd.read_excel(f, nrows=20) 
        else:
            df = pd.read_excel(f, nrows=20)

        print(df.head(20))
